reference_solution:
def user_active_minute_counts(logs, k):
 minutes={}
 for user,minute in logs:minutes.setdefault(user,set()).add(minute)
 answer=[0]*k
 for values in minutes.values():answer[len(values)-1]+=1
 return answer

